@classmethod
def from_config(cls, config):
    query_shape = config.pop('query_shape')
    key_shape = config.pop('key_shape')
    value_shape = config.pop('value_shape')
    layer = cls(**config)
    if None in [query_shape, key_shape, value_shape]:
        logging.warning('One of dimensions of the input shape is missing. It should have been memorized when the layer was serialized. %s is created without weights.', str(cls))
    else:
        layer._build_from_signature(query_shape, value_shape, key_shape)
    return layer

def _make_output_dense(self, free_dims, common_kwargs, name=None):
    """Builds the output projection matrix.

        Args:
          free_dims: Number of free dimensions for einsum equation building.
          common_kwargs: Common keyword arguments for einsum layer.
          name: Name for the projection layer.

        Returns:
          Projection layer.
        """
    if self._output_shape:
        if not isinstance(self._output_shape, collections.abc.Sized):
            output_shape = [self._output_shape]
        else:
            output_shape = self._output_shape
    else:
        output_shape = [self._query_shape[-1]]
    einsum_equation, bias_axes, output_rank = _build_proj_equation(free_dims, bound_dims=2, output_dims=len(output_shape))
    return core.EinsumDense(einsum_equation, output_shape=_get_output_shape(output_rank - 1, output_shape), bias_axes=bias_axes if self._use_bias else None, name=name, **common_kwargs)

def _masked_softmax(self, attention_scores, attention_mask=None):
    if attention_mask is not None:
        mask_expansion_axis = -len(self._attention_axes) * 2 - 1
        for _ in range(len(attention_scores.shape) - len(attention_mask.shape)):
            attention_mask = tf.expand_dims(attention_mask, axis=mask_expansion_axis)
    return self._softmax(attention_scores, attention_mask)

def call(self, query, value, key=None, attention_mask=None, return_attention_scores=False, training=None):
    if not self._built_from_signature:
        self._build_from_signature(query=query, value=value, key=key)
    if key is None:
        key = value
    query_is_ragged = isinstance(query, tf.RaggedTensor)
    if query_is_ragged:
        query_lengths = query.nested_row_lengths()
        query = query.to_tensor()
    key_is_ragged = isinstance(key, tf.RaggedTensor)
    value_is_ragged = isinstance(value, tf.RaggedTensor)
    if key_is_ragged and value_is_ragged:
        bounding_shape = tf.math.maximum(key.bounding_shape(), value.bounding_shape())
        key = key.to_tensor(shape=bounding_shape)
        value = value.to_tensor(shape=bounding_shape)
    elif key_is_ragged:
        key = key.to_tensor(shape=tf.shape(value))
    elif value_is_ragged:
        value = value.to_tensor(shape=tf.shape(key))
    query = self._query_dense(query)
    key = self._key_dense(key)
    value = self._value_dense(value)
    attention_output, attention_scores = self._compute_attention(query, key, value, attention_mask, training)
    attention_output = self._output_dense(attention_output)
    if query_is_ragged:
        attention_output = tf.RaggedTensor.from_tensor(attention_output, lengths=query_lengths)
    if return_attention_scores:
        return (attention_output, attention_scores)
    return attention_output
